"use client";

import { useRef } from "react";
import { motion, useReducedMotion, useScroll, useTransform, type Variants } from "motion/react";
import ArrowDownRight from "@/components/ArrowDownRight";

const EASE_OUT: [number, number, number, number] = [0.22, 1, 0.36, 1];

const STACK = ["Next.js", "React", "TypeScript", "Node", "Postgres", "Tailwind", "Turborepo"];

const container: Variants = {
  hidden: {},
  show: { transition: { staggerChildren: 0.09, delayChildren: 0.15 } },
};

const item: Variants = {
  hidden: { opacity: 0, y: 28 },
  show: { opacity: 1, y: 0, transition: { duration: 0.8, ease: EASE_OUT } },
};

/* Masked reveal for the display headline — slides up from behind the fold */
const headline: Variants = {
  hidden: { y: "85%", opacity: 0 },
  show: { y: "0%", opacity: 1, transition: { duration: 1, ease: EASE_OUT } },
};

export default function Hero() {
  const sectionRef = useRef<HTMLElement | null>(null);
  const reduced = useReducedMotion();
  const { scrollYProgress } = useScroll({
    target: sectionRef,
    offset: ["start start", "end start"],
  });

  const contentY = useTransform(scrollYProgress, [0, 1], [0, 110]);
  const contentOpacity = useTransform(scrollYProgress, [0, 0.8], [1, 0]);
  const cornersOpacity = useTransform(scrollYProgress, [0, 0.55], [1, 0]);

  return (
    <section
      id="overview"
      ref={sectionRef}
      className="relative flex min-h-screen flex-col items-center justify-center px-6 text-center"
    >
      {/* Corner mono labels — fade out first as the hero scrolls away */}
      <motion.div
        aria-hidden
        className="pointer-events-none absolute inset-0"
        style={reduced ? undefined : { opacity: cornersOpacity }}
      >
        <span className="mono-label absolute top-[98px] left-6 text-mute">01 / Overview</span>
        <span className="mono-label absolute top-[98px] right-[84px] hidden text-mute sm:block lg:hidden">
          Fullstack Architect
        </span>
        <span className="mono-label absolute bottom-8 left-6 hidden text-mute md:block">
          EST. 2019 · UTC+01:00
        </span>
        <span className="mono-label absolute right-[84px] bottom-8 text-mute lg:right-[176px]">
          Scroll{" "}
          <motion.span
            className="inline-block"
            animate={reduced ? undefined : { y: [0, 4, 0] }}
            transition={reduced ? undefined : { repeat: Infinity, duration: 1.6, ease: "easeInOut" }}
          >
            <span className="text-ship">↓</span>
          </motion.span>
        </span>
      </motion.div>

      {/* Centered content — staggered entrance, parallax exit */}
      <motion.div
        className="flex flex-col items-center"
        variants={reduced ? undefined : container}
        initial={reduced ? undefined : "hidden"}
        animate={reduced ? undefined : "show"}
        style={reduced ? undefined : { y: contentY, opacity: contentOpacity }}
      >
        <motion.span variants={reduced ? undefined : item} className="badge">
          06+
        </motion.span>

        <div className="overflow-hidden py-[0.06em]">
          <motion.h1
            variants={reduced ? undefined : headline}
            className="font-display text-[clamp(3.25rem,8.5vw,7.5rem)] font-black uppercase leading-[0.9] tracking-[-0.075em]"
          >
            Design I <span className="text-ship">Ship</span>
          </motion.h1>
        </div>

        <motion.p
          variants={reduced ? undefined : item}
          className="mt-8 max-w-2xl text-lg font-medium leading-relaxed text-mute"
        >
          A fullstack architect with a designer&rsquo;s discipline. Design systems, product
          interfaces and backend architecture — numbered, built and shipped by the same pair of
          hands.
        </motion.p>

        <motion.div
          variants={reduced ? undefined : item}
          className="mt-12 flex flex-wrap items-center justify-center gap-4"
        >
          <a href="#competencies" className="btn-primary">
            Explore the system <ArrowDownRight />
          </a>
          <a href="#contact" className="btn-ghost">
            Book a call
          </a>
        </motion.div>

        <motion.p variants={reduced ? undefined : item} className="mono-label mt-16 text-mute">
          {STACK.map((s, i) => (
            <span key={s}>
              {i > 0 && <span className="text-ship"> — </span>}
              {s}
            </span>
          ))}
        </motion.p>
      </motion.div>
    </section>
  );
}
